public sealed partial class FreshGlobalCacheMySqlTests
{
    private const string Shared="gs_single_shared",Tenant="gs_single_tenant",Middle="gs_cache_middle",Tail="gs_cache_tail",Original="甲_%!引号'记录",Second="乙记录";
    /// <summary>每轮只写已核实例的独占新库；批量参数化样本避免数千次单行网络往返。</summary>
    private static async Task SeedCross(Probe p)
    {
        await p.Session.InTransactionAsync(async()=>{await InsertMany(p,"gs_single_parent",Enumerable.Range(0,3).Select(i=>Row("id",Parent+i,"name","来源父"+i,"yz_project_id",i==2?Project+1:Project)).ToArray());await InsertMany(p,Shared,new[]{SharedRow(p,First,Original,1,1),SharedRow(p,First+1,Second,1,1),SharedRow(p,First+2,"禁用",0,1),SharedRow(p,First+3,"另一组",1,2),SharedRow(p,First+5,"重复名",1,1),SharedRow(p,First+6,"重复名",1,1)});await InsertMany(p,Tenant,new[]{Row("id",First+10000,"name","项目候选","yz_project_id",Project,"status",1,"segment",1),Row("id",First+10001,"name","外项目候选","yz_project_id",Project+1,"status",1,"segment",1)});await InsertMany(p,Middle,Enumerable.Range(0,3).Select(i=>Row("id",First+20000+i,"shared_id",First+(i==1?1:0),"yz_project_id",i==2?Project+1:Project)).ToArray());var sources=Enumerable.Range(0,130).Select(i=>SourceRow(p,First+30000+i,Project,"缓存消费者拒绝钩子")).Append(SourceRow(p,First+900000,Project+1,"外项目消费者")).ToArray();await InsertMany(p,p.Source,sources);await InsertMany(p,Tail,sources.Select((row,i)=>TailRow(p,First+40000+i,(long)row["id"]!,i==130?Project+1:Project,"尾旧缓存")).ToArray());return true;});
    }
    /// <summary>完整原CRUD、字典改名／删除、当前项目传播、回填与晚期文件失败走真实生产宿主。</summary>
    private static async Task VerifyCross(Probe p)
    {
        var name=Original;var score=1.25m;var ids=new[]{Id(First),Id(First+1)};var bytes=Encoding.UTF8.GetBytes("全局缓存原文件");var file=await p.Upload(bytes);
        var options=await p.Post("findNameIdGlobal2301/page",new{parentId=p.ParentId,pageNo=1,pageSize=1,keyword=Original,formParameters=new{segment=1}});Assert.Equal("1",options.GetProperty("total").GetString());var nested=await p.Post("findNameIdNested2308/page",new{parentId=p.ParentId,pageNo=1,pageSize=1,keyword=Original});Assert.Equal("1",nested.GetProperty("total").GetString());var added=await p.Post("add",new{name="缓存正式来源",globalId=Id(First),selectedId=Id(First+1),sharedIds=ids,checkedIds=ids,tenantIds=new[]{Id(First+10000)},nestedId=Id(First+20000),segment=1,attachments=new[]{file}});p.RecordId=added.GetProperty("id").GetString()!;await p.Store.InsertAsync(Tail,TailRow(p,First+50000,long.Parse(p.RecordId,CultureInfo.InvariantCulture),Project,name));Check(added);await p.References(file,1);await p.Download(file,bytes);
        // MySQL原TEXT默认值可参与回填，但真实生成列必须仍被结构保护拒绝，失败不得写任何业务值。
        var cacheColumn=Metarill.Data.Schema.MySqlSchemaPlanner.CompileColumn(p.Catalog.ConfigColumns.Single(x=>x.Id=="2303"));var schemaBefore=await p.Snapshot();await Sql("ALTER TABLE `"+p.Source+"` DROP COLUMN `global_score`, ADD COLUMN `global_score` "+cacheColumn.StoreType+" GENERATED ALWAYS AS (1.25) STORED");try{var generatedBefore=await p.Snapshot();await p.Send(p.Reader,HttpMethod.Post,"/api/admin/sys/system_maintenance/backfill_join_columns",new{configTableId="2"},HttpStatusCode.InternalServerError);Assert.Equal(generatedBefore,await p.Snapshot());}finally{await Sql("ALTER TABLE `"+p.Source+"` DROP COLUMN `global_score`, ADD COLUMN `global_score` "+cacheColumn.StoreType+" NULL");await Sql("UPDATE `"+p.Source+"` SET `global_score`=1.25");}Assert.Equal(schemaBefore,await p.Snapshot());
        var before=await p.Snapshot();foreach(var bad in new object[]{new{id=p.RecordId,globalId=Id(First+2)},new{id=p.RecordId,tenantIds=new[]{Id(First+10001)}},new{id=p.RecordId,segment=2},new{id=p.RecordId,nestedId=Id(First+20002)}}){await p.Post("update",bad,HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());}await p.Post("update",new{id=Id(First+900000),name="跨项目修改"},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());if(p.ParentScope){await p.Post("update?parentId="+Id(Parent+1),new{id=p.RecordId,name="跨父"},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());}
        var echo=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(added.GetRawText())!;foreach(var field in new[]{"globalName","selectedName","nestedLabel"})echo[field]=JsonSerializer.SerializeToElement("伪造");echo["globalScore"]=JsonSerializer.SerializeToElement(999m);echo["checkedNames"]=JsonSerializer.SerializeToElement(new[]{"伪造"});Check(await p.Post("update",echo));
        var foreignBefore=await ForeignRows();var idsBefore=await IdRows();name="全局新_%!名称'";await TargetUpdate(new{name});await AssertConsumers();Assert.Equal(idsBefore,await IdRows());Assert.Equal(foreignBefore,await ForeignRows());score=8.5m;await TargetUpdate(new{score});await AssertConsumers();
        await p.Store.UpdateAsync(Shared,First,Row("status",0));try{before=await p.Snapshot();await p.Post("add",new{name="隐藏默认拒绝",globalId=Id(First+1),selectedId=Id(First+1),sharedIds=new[]{Id(First+1)},checkedIds=new[]{Id(First+1)},segment=1},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());}finally{await p.Store.UpdateAsync(Shared,First,Row("status",1));}
        await p.Grant("301","[]");await p.Post("findNameIdGlobal2301/page",new{parentId=p.ParentId,pageNo=1,pageSize=1,formParameters=new{segment=1}},HttpStatusCode.Forbidden);await p.Grant("302","[]");await p.Grant("303","[]");await p.Grant("402","[]");await p.Grant(p.SourcePage,"[\"is_update\",\"is_export\"]");Check(await p.Post("update",new{id=p.RecordId,globalId=Id(First),selectedId=Id(First+1)}));before=await p.Snapshot();await p.Post("update",new{id=p.RecordId,sharedIds=ids},HttpStatusCode.Forbidden);Assert.Equal(before,await p.Snapshot());await p.Post("findNameIdChecked2204",new{parentId=p.ParentId,formParameters=new{segment=1}});await p.Post("update",new{id=p.RecordId,checkedIds=ids});await p.Download(file,bytes,HttpStatusCode.Unauthorized);await p.Grant(p.SourcePage,"[\"is_all\"]");await p.Post("importDatas201",new{parentId=p.ParentId,requestJson=new[]{Import("无独立目标权限导入",name)}});foreach(var page in new[]{"301","302","303","402"})await p.Grant(page,"[\"is_all\"]");
        before=await p.Snapshot();await p.Post("importDatas201",new{parentId=p.ParentId,requestJson=new[]{Import("整批首行",name),Import("整批尾行","不存在")}},HttpStatusCode.BadRequest);Assert.Equal(before,await p.Snapshot());await p.Post("importDatas201",new{parentId=p.ParentId,requestJson=new[]{Import("重名拒绝","重复名")}},HttpStatusCode.BadRequest);Assert.Equal(before,await p.Snapshot());
        var ticket=(await p.Post("initExport",new PageRequest{SelectedIds=[p.RecordId]})).GetString()!;using(var response=await p.Reader.GetAsync(ExportDownloadAccess.DownloadPath+"?exportId="+Uri.EscapeDataString(ticket))){Assert.Equal(HttpStatusCode.OK,response.StatusCode);using var book=new XLWorkbook(new MemoryStream(await response.Content.ReadAsByteArrayAsync()));var sheet=book.Worksheet(1);var columns=sheet.Row(1).CellsUsed().ToDictionary(x=>x.GetString(),x=>x.Address.ColumnNumber);Assert.Equal(name,sheet.Row(2).Cell(columns["全局下拉"]).GetString());Assert.Equal(ids,JsonSerializer.Deserialize<string[]>(sheet.Row(2).Cell(columns["共享复选"]).GetString()));}
        // 原维护入口修复整表派生值，原ID和其它项目保持；第二次执行应为零。
        await p.Store.UpdateAsync(p.Source,long.Parse(p.RecordId,CultureInfo.InvariantCulture),Row("global_name","故意旧名","global_score",0m,"nested_label","故意旧名"));var maintained=await Backfill("2");Assert.True(maintained.GetProperty("affectedRows").GetInt32()>0);Check((await p.Send(p.Reader,HttpMethod.Get,p.Route+"detail/"+p.RecordId)).GetProperty("data"));Assert.Equal(0,(await Backfill("2")).GetProperty("affectedRows").GetInt32());Assert.Equal(foreignBefore,await ForeignRows());
        // 晚批失败必须撤销此前已更新目标、前批消费者与下游。
        var constraint="mt_gc_tail_"+Guid.NewGuid().ToString("N")[..12];var installed=false;try{await Sql("ALTER TABLE `"+Tail+"` ADD CONSTRAINT `"+constraint+"` CHECK (`source_id` <> "+(First+30000+129).ToString(CultureInfo.InvariantCulture)+" OR `source_global_name` <> 'late-global-failure')");installed=true;before=await p.Snapshot();await TargetUpdate(new{name="late-global-failure"},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());await Sql("ALTER TABLE `"+Tail+"` DROP CHECK `"+constraint+"`");installed=false;}finally{if(installed)await Sql("ALTER TABLE `"+Tail+"` DROP CHECK `"+constraint+"`");}
        // 原目标删除方式由元数据决定；缺失名称置空，引用ID及外项目记录不动。
        idsBefore=await IdRows();await p.Send(p.Owner,HttpMethod.Delete,"/api/admin/auto/"+Shared+"/301/",new{id=Id(First)});await AssertConsumers(missing:true);Assert.Equal(idsBefore,await IdRows());Assert.Equal(foreignBefore,await ForeignRows());if(p.TargetSoftDelete)await p.Store.UpdateAsync(Shared,First,Row("delete_no",null));else await p.Store.InsertAsync(Shared,SharedRow(p,First,name,1,1,score));await Backfill("2");await AssertConsumers();
        if(p.Profile=="cross7")await LargeCache(p,name);
        var copy=(await p.Post("copy/"+p.RecordId,new{})).GetProperty("id").GetString()!;await p.References(file,2);var secondBytes=Encoding.UTF8.GetBytes("缓存晚期文件");var second=await p.Upload(secondBytes);constraint="mt_gc_file_"+Guid.NewGuid().ToString("N")[..12];var late=new{id=p.RecordId,name="晚期来源写入",globalId=Id(First+1),attachments=new[]{second}};try{await Sql("ALTER TABLE `yz_file_ref` ADD CONSTRAINT `"+constraint+"` CHECK (`file_id` <> "+long.Parse(second,CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture)+")");installed=true;before=await p.Snapshot();await p.Post("update",late,HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());await Sql("ALTER TABLE `yz_file_ref` DROP CHECK `"+constraint+"`");installed=false;await p.Post("update",late);Assert.Equal(Second,SqlRowStore.Text(Assert.Single(await p.Store.ReadAsync(Tail,Row("id",First+50000))),"source_global_name"));await p.References(second,1);await p.References(file,1);}finally{if(installed)await Sql("ALTER TABLE `yz_file_ref` DROP CHECK `"+constraint+"`");}await p.Post("update",new{id=p.RecordId,globalId=Id(First)});await p.Send(p.Reader,HttpMethod.Delete,p.Route,new{id=copy});await p.References(file,0);await p.References(second,1);await p.Download(second,secondBytes);await p.Grant(p.SourcePage,"[]");await p.Post("page",new PageRequest(),HttpStatusCode.Forbidden);await p.Grant(p.SourcePage,"[\"is_all\"]");
        /// <summary>保留原Excel格式：单值和多选按名称匹配，R1数据库复选沿用ID数组。</summary>
        static Dictionary<string,object?> Import(string record,string name)=>Row("记录名",record,"全局下拉",name,"全局单选",Second,"共享多选",JsonSerializer.Serialize(new[]{name,Second}),"共享复选",JsonSerializer.Serialize(new[]{Id(First),Id(First+1)}),"项目多选",JsonSerializer.Serialize(new[]{"项目候选"}),"中间节点",name,"分组",1);
        /// <summary>缓存回执必须使用当前值，ID不能误联相邻大整数。</summary>
        void Check(JsonElement row){Assert.Equal(Id(First),row.GetProperty("globalId").GetString());Assert.Equal(name,row.GetProperty("globalName").GetString());Assert.Equal(score,row.GetProperty("globalScore").GetDecimal());Assert.Equal(Second,row.GetProperty("selectedName").GetString());Assert.Equal(name,row.GetProperty("nestedLabel").GetString());Assert.Equal(new[]{name,Second},row.GetProperty("checkedNames").EnumerateArray().Select(x=>x.GetString()));}
        /// <summary>字典普通更新使用原控制器，禁止请求提供项目或计划。</summary>
        async Task TargetUpdate(object values,HttpStatusCode expected=HttpStatusCode.OK){var body=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(JsonSerializer.Serialize(values))!;body["id"]=JsonSerializer.SerializeToElement(Id(First));await p.Send(p.Owner,HttpMethod.Post,"/api/admin/auto/"+Shared+"/301/update",body,expected);}
        /// <summary>当前项目全部活动消费者、130行跨批与下游都要一致，不能只检查首行。</summary>
        async Task AssertConsumers(bool missing=false){var rows=(await p.Store.ReadIncludingDeletedAsync(p.Source)).Where(x=>SqlRowStore.Text(x,"yz_project_id")==Id(Project)&&x.GetValueOrDefault("delete_no") is null).ToArray();Assert.True(rows.Length>=131);foreach(var row in rows){Assert.Equal(missing?null:score,row.GetValueOrDefault("global_score") is null?null:(decimal?)Convert.ToDecimal(row["global_score"],CultureInfo.InvariantCulture));Assert.Equal(missing?null:name,SqlRowStore.Text(row,"global_name") is ""?null:SqlRowStore.Text(row,"global_name"));Assert.Equal(missing?null:name,SqlRowStore.Text(row,"nested_label") is ""?null:SqlRowStore.Text(row,"nested_label"));var names=JsonSerializer.Deserialize<string?[]>(SqlRowStore.Text(row,"checked_names"))!;Assert.Equal(new[]{missing?null:name,Second},names);}var tails=(await p.Store.ReadAsync(Tail,Row("yz_project_id",Project))).ToArray();Assert.True(tails.Length>=131);Assert.All(tails,row=>Assert.Equal(missing?null:name,SqlRowStore.Text(row,"source_global_name") is ""?null:SqlRowStore.Text(row,"source_global_name")));}
        /// <summary>只比较来源关联ID，传播与回填不得修补或重新映射。</summary>
        async Task<string> IdRows()=>JsonSerializer.Serialize((await p.Store.ReadIncludingDeletedAsync(p.Source)).OrderBy(x=>SqlRowStore.Id(x)).Select(x=>new{xid=SqlRowStore.Id(x),a=x.GetValueOrDefault("global_id"),b=x.GetValueOrDefault("selected_id"),c=x.GetValueOrDefault("shared_ids"),d=x.GetValueOrDefault("checked_ids"),e=x.GetValueOrDefault("nested_id")}));
        /// <summary>外项目消费者包含缓存与业务值，任何传播路径均不能触碰。</summary>
        async Task<string> ForeignRows()=>JsonSerializer.Serialize(new{source=await p.Store.ReadIncludingDeletedAsync(p.Source,Row("yz_project_id",Project+1)),tail=await p.Store.ReadIncludingDeletedAsync(Tail,Row("yz_project_id",Project+1))});
        async Task<JsonElement> Backfill(string table)=>(await p.Send(p.Reader,HttpMethod.Post,"/api/admin/sys/system_maintenance/backfill_join_columns",new{configTableId=table})).GetProperty("data");
        async Task Sql(string sql){await using var connection=p.Session.Provider.CreateConnection(p.Session.Options);await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=sql;await command.ExecuteNonQueryAsync();}
    }
    /// <summary>5000项复选缓存与原回填保持全部名称，字典更新不截断数组。</summary>
    private static async Task LargeCache(Probe p,string name)
    {
        var ids=new[]{Id(First)}.Concat(Enumerable.Range(0,4999).Select(i=>Id(First+100000+i))).ToArray();await p.Session.InTransactionAsync(async()=>{await InsertMany(p,Shared,Enumerable.Range(0,4999).Select(i=>SharedRow(p,First+100000+i,"大缓存"+i,1,1)).ToArray());return true;});await p.Post("update",new{id=p.RecordId,checkedIds=ids});await p.Send(p.Owner,HttpMethod.Post,"/api/admin/auto/"+Shared+"/301/update",new{id=Id(First),name="5000项改名"});var row=Assert.Single(await p.Store.ReadAsync(p.Source,Row("id",long.Parse(p.RecordId,CultureInfo.InvariantCulture))));var names=JsonSerializer.Deserialize<string?[]>(SqlRowStore.Text(row,"checked_names"))!;Assert.Equal(5000,names.Length);Assert.Equal("5000项改名",names[0]);Assert.Equal("大缓存4998",names[^1]);
        // 有5000项名称数组时只改标量，所需分值须刷新，无关数组文本和ID均不能被重写。
        var oldScore=Convert.ToDecimal(Assert.Single(await p.Store.ReadAsync(Shared,Row("id",First)))["score"],CultureInfo.InvariantCulture);var arrayBefore=SqlRowStore.Text(row,"checked_names");var idsBefore=SqlRowStore.Text(row,"checked_ids");await p.Send(p.Owner,HttpMethod.Post,"/api/admin/auto/"+Shared+"/301/update",new{id=Id(First),score=oldScore+0.75m});var scalar=Assert.Single(await p.Store.ReadAsync(p.Source,Row("id",long.Parse(p.RecordId,CultureInfo.InvariantCulture))));Assert.Equal(oldScore+0.75m,Convert.ToDecimal(scalar["global_score"],CultureInfo.InvariantCulture));Assert.Equal(arrayBefore,SqlRowStore.Text(scalar,"checked_names"));Assert.Equal(idsBefore,SqlRowStore.Text(scalar,"checked_ids"));await p.Send(p.Owner,HttpMethod.Post,"/api/admin/auto/"+Shared+"/301/update",new{id=Id(First),score=oldScore});
        await p.Send(p.Reader,HttpMethod.Post,"/api/admin/sys/system_maintenance/backfill_join_columns",new{configTableId="2"});Assert.Equal(ids,JsonSerializer.Deserialize<string[]>(SqlRowStore.Text(Assert.Single(await p.Store.ReadAsync(p.Source,Row("id",long.Parse(p.RecordId,CultureInfo.InvariantCulture)))),"checked_ids")));await p.Send(p.Owner,HttpMethod.Post,"/api/admin/auto/"+Shared+"/301/update",new{id=Id(First),name});await p.Post("update",new{id=p.RecordId,checkedIds=new[]{Id(First),Id(First+1)}});
    }
    /// <summary>共同字典行只包含本轮元数据实际声明列。</summary>
    private static Dictionary<string,object?> SharedRow(Probe p,long id,string name,int status,int segment,decimal score=1.25m){var row=Row("id",id,"name",name,"status",status,"segment",segment,"score",id==First+1?2.25m:score);if(!p.NoProject)row["yz_project_id"]=Project+1;return row;}
    /// <summary>R1来源只预置旧标量缓存，多值缓存由真实传播补齐，兼容自动物理名称列。</summary>
    private static Dictionary<string,object?> SourceRow(Probe p,long id,long project,string name)=>Row("id",id,"name",name,"yz_project_id",project,"parent_id",Parent,"segment",1,"global_id",p.Key(First),"selected_id",First+1,"shared_ids",JsonSerializer.Serialize(new[]{Id(First),Id(First+1)}),"checked_ids",JsonSerializer.Serialize(new[]{Id(First),Id(First+1)}),"tenant_ids",JsonSerializer.Serialize(new[]{Id(First+10000)}),"hidden_ids",JsonSerializer.Serialize(new[]{Id(First)}),"hidden_id",First,"nested_id",First+20000,"global_name","旧缓存","global_score",1.25m,"selected_name",Second,"nested_label","旧缓存","hidden_name","旧缓存");
    private static Dictionary<string,object?> TailRow(Probe p,long id,long source,long project,string cache){var row=Row("id",id,"yz_project_id",project,"source_id",source,"source_global_name",cache);if(p.ParentScope)row["parent_id"]=Parent;return row;}
    /// <summary>只对当前已核租约库的固定元数据表批量参数化插入，不拼接业务值。</summary>
    private static async Task InsertMany(Probe p,string table,IReadOnlyList<Dictionary<string,object?>> rows)
    {
        if(rows.Count==0)return;if(!p.Catalog.ConfigTables.Any(x=>x.TableName==table))throw new InvalidOperationException("验收表不属于本轮发布模型。");var transaction=p.Session.CurrentTransaction??throw new InvalidOperationException("样本批量写入要求显式事务。");var columns=rows[0].Keys.ToArray();Assert.All(rows,row=>Assert.Equal(columns,row.Keys));foreach(var batch in rows.Chunk(200)){await using var command=transaction.Connection!.CreateCommand();command.Transaction=transaction;command.CommandText="INSERT INTO "+p.Session.Provider.QuoteIdentifier(table)+" ("+string.Join(",",columns.Select(p.Session.Provider.QuoteIdentifier))+") VALUES "+string.Join(",",batch.Select((row,i)=>"("+string.Join(",",columns.Select((column,j)=>"@v"+i+"_"+j))+")"));for(var i=0;i<batch.Length;i++)for(var j=0;j<columns.Length;j++){var parameter=command.CreateParameter();parameter.ParameterName="v"+i+"_"+j;parameter.Value=batch[i][columns[j]]??DBNull.Value;command.Parameters.Add(parameter);}await command.ExecuteNonQueryAsync();}
    }
}
